// src/store/canonical.ts
function canonical(value) {
  if (value === null)
    return "null";
  switch (typeof value) {
    case "boolean":
      return value ? "true" : "false";
    case "number":
      if (!Number.isFinite(value))
        throw new Error(`not a JSON number: ${value}`);
      return JSON.stringify(value);
    case "string":
      if (!value.isWellFormed())
        throw new Error("a string with a lone surrogate");
      return JSON.stringify(value);
    case "object": {
      if (Array.isArray(value)) {
        if (Array.from(value.keys()).some((i) => !(i in value)))
          throw new Error("an array with a hole");
        return `[${value.map(canonical).join(",")}]`;
      }
      const proto = Object.getPrototypeOf(value);
      if (proto !== Object.prototype && proto !== null)
        throw new Error("not a plain object");
      const keys = Object.keys(value).sort();
      const record = value;
      return `{${keys.filter((key) => record[key] !== undefined).map((key) => `${canonical(key)}:${canonical(record[key])}`).join(",")}}`;
    }
    default:
      throw new Error(`not JSON: ${typeof value}`);
  }
}

